code='''from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v)
    boxes = []
    frame_colors = set()
    for color, total in counts.items():
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                     if r in (r0,r1) or c in (c0,c1)}
        if len(cells) == len(perimeter) and all(grid[r][c] == color for r,c in perimeter):
            boxes.append((color,r0,r1,c0,c1))
            frame_colors.add(color)
    result = [[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in boxes:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    result[r][c] = color
        inside = (r1-r0-1)*(c1-c0-1)
        target = next((v for v,n in counts.items() if v not in frame_colors and n == inside//2), None)
        if target is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r+c)%2 == 0:
                        result[r][c] = target
    return result
'''
